import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 5-dimensional benchmark function.
    """
    if x.shape != (5,):
        raise ValueError("Input must be a 5-dimensional NumPy array.")

    x_scaled = x / 5.0
    return 0.5 * np.sum(x_scaled**2) + 0.1 * np.sum(x_scaled[:-1] * x_scaled[1:]) + 0.2*x_scaled[0] + 0.1 * np.sum(np.sin(x_scaled))

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    scaling = np.array([1.0, 0.8, 0.6, 0.4, 0.2])
    linear_sum = np.sum(x * scaling)
    return linear_sum + 0.25 * np.sin(linear_sum)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    scaling = np.array([1.0, 0.8, 0.6, 0.4, 0.2])
    linear_sum = np.sum(x * scaling)
    return linear_sum + 0.25 * np.sin(linear_sum) + 0.05 * np.cos(linear_sum)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    scaling = np.array([1.0, 0.8, 0.6, 0.4, 0.2])
    linear_sum = np.sum(x * scaling)
    return linear_sum + 0.25 * np.sin(linear_sum) + 0.1 * np.arctan(linear_sum)

