import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    scaling = np.array([1.0, 0.8, 0.6, 0.4, 0.2])
    linear_sum = np.sum(x * scaling)
    return linear_sum + 0.25 * np.sin(linear_sum) + 0.1 * np.arctan(linear_sum) + 0.05 * (1 / (1 + np.exp(-x[0]))) * np.cbrt(x[0])

